package com.biocircular.compostaje.repository; import com.biocircular.compostaje.entity.Lote; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface LoteRepository extends JpaRepository<Lote,UUID>, JpaSpecificationExecutor<Lote>{ @Query("select l from Lote l left join fetch l.ingresos where l.id=:id") Optional<Lote> findWithIngresosById(@Param("id") UUID id); }
